from ute_ue.mbms_sessions.mbms_session import MbmsSession
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.server_commands import MBMS_SESSION
from ute_ue.exceptions import MbmsSessionVerificationFailure


class QualcommMbmsSession(MbmsSession):
    """Qualcomm MBMS Session"""

    SESION_EXTRACTION_COMMAND = r'logcat mfosal *:D *:S'

    def __init__(self, service_name, configuration, qualcomm_ue, logger_name='ute_ue'):
        """

        :param service_name:
        :param configuration:
        :param qualcomm_ue:
        """
        super(QualcommMbmsSession, self).__init__(service_name, configuration, logger_name)
        self.ue = qualcomm_ue
        self.is_verification_in_progress = False

    def start_verifying(self):
        """
        Starts mbms session verification
        :return:
        """
        status, messages = self.ue.ue_pc_handler.send(MBMS_SESSION.START_VERIFYING,
                                                      alias=self.ue.name,
                                                      ue_type=self.ue.ue_type,
                                                      ue_id=self.ue.serial_number,
                                                      command_parameters=self.SESION_EXTRACTION_COMMAND,
                                                      mbms_session_alias=self.name,
                                                      ue_sn=self.ue.serial_number)
        if status:
            self.is_verification_in_progress = True
        self.logger.info("MBMS_SESSION [%s] on Ue [%s] START_VERIFYING, status:%s, messages:%s" % (self.name, self.ue.name, status, messages))

    def stop_verifying(self):
        """
        Stops mbms session verification
        :return:
        """
        if self.is_verification_in_progress:
            status, messages = self.ue.ue_pc_handler.send(MBMS_SESSION.STOP_VERIFYING, alias=self.ue.name,
                                                          mbms_session_alias=self.name, ue_sn=self.ue.serial_number)
            self.is_verification_in_progress = False
            self.logger.info("MBMS_SESSION [%s] on Ue [%s] STOP_VERIFYING, status:%s, messages:%s" % (self.name, self.ue.name, status, messages))
        else:
            self.logger.info("MBMS_SESSION [%s] on Ue [%s] STOP_VERIFYING, Session verification already stopped. "
                             "No further actions" % (self.name, self.ue.name))

    def get_statistics(self):
        """
        Return mbms session statistics
        :return: statistics_dict
        :raises: :py:class:`ute_ue.exceptions.MbmsSessionVerificationFailure`: If cannot get mbms session statistics
        """
        status, statistics_dict = self.ue.ue_pc_handler.send(MBMS_SESSION.GET_STATISTICS, alias=self.ue.name,
                                                             mbms_session_alias=self.name, ue_sn=self.ue.serial_number)
        if status:
            self.logger.info("MBMS_SESSION [%s] on Ue [%s] GET_STATISTICS, status:%s, messages:%s" % (self.name, self.ue.name,
                                                                                                      status, statistics_dict))
            return statistics_dict
        else:
            raise MbmsSessionVerificationFailure("Failed to get statistics of MbmsSession with alias '{}' on UE {}".format(self.name, self.ue.name))

    def get_success_rate(self):
        """
        Return mbms session success rate
        :return: success_rate
        :raises: :py:class:`ute_ue.exceptions.MbmsSessionVerificationFailure`: If cannot get mbms session success rate
        """
        try:
            return self.get_statistics()['success_rate']
        except KeyError:
            raise MbmsSessionVerificationFailure("Failed to get success_rate of MbmsSession with alias '{}' on UE {}."
                                                 "Statistics: {}".format(self.name, self.ue.name, self.get_statistics()))

    def reset_statistics(self):
        """
        Reset mbms session statistics
        :return:
        :raises: :py:class:`ute_ue.exceptions.MbmsSessionVerificationFailure`: If reset mbms session statistics failed
        """
        status, messages = self.ue.ue_pc_handler.send(MBMS_SESSION.RESET_STATISTICS, alias=self.ue.name,
                                                      mbms_session_alias=self.name, ue_sn=self.ue.serial_number)
        if status:
            self.logger.info("MBMS_SESSION [%s] on Ue [%s] RESET_STATISTICS, status:%s, messages:%s" % (self.name, self.ue.name, status, messages))
        else:
            raise MbmsSessionVerificationFailure("Failed to reset statistics of MbmsSession with alias '{}' on UE {}".format(self.name, self.ue.name))

    def is_being_verified(self):
        """
        Check if mbms session is being verified

        :return: boolean
        """
        return self.is_verification_in_progress
